    ]
  },
  {
    "alert_id": "EX2_003",
    "title": "DTG creatinine rise does not apply here",
    "message": "Guidelines describe a benign DTG-related creatinine rise of <30 µmol/L occurring within the first month of initiation, which does not progress after that. This patient has been on DTG for 2 years with previously normal creatinine (0.9 mg/dL), and the current rise to 2.4 mg/dL represents an increase of ~133 µmol/L — far exceeding the DTG-related threshold and occurring acutely with dehydration. This pattern is inconsistent with DTG-related creatinine elevation and supports an alternative cause.",
    "issue_type": "toxicity",
